function localTerm(iri){if(iri.startsWith('"'))return iri;let p=iri.match(/[#/]([^#/]*)$/);return p?decodeURIComponent(p[1]):iri;}
// Deterministic offline Turtle teaching parser. Supports prefixes, ; , shorthand and multiple statements.
// Advanced Turtle constructs such as collections, [] blank-node property lists, multiline strings and RDF-star are intentionally excluded.
function parseStarterTurtle(input){
  const prefix={...BASE_PREFIXES},quads=[];
  let text=input.replace(/\r\n?/g,'\n');
  text=text.replace(/(?:^|\n)\s*(?:@prefix|PREFIX)\s+([\w-]*):\s*<([^<>\s]+)>\s*(\.)?\s*(?=\n|$)/gim,(_,p,url)=>{prefix[p]=url;return '\n';});
  const tokenPattern=/(?:\s+|#[^\n]*|"(?:\\.|[^"\\])*"(?:@[a-zA-Z]+(?:-[a-zA-Z0-9]+)*|\^\^(?:<[^<>]+>|[\w-]*:[\w.-]+))?|<[^<>\s]+>|[\w-]*:[A-Za-z_0-9-]+(?:\.[A-Za-z_0-9-]+)*|_:[A-Za-z][\w-]*|[+-]?\d+(?:\.\d+)?|[;,\.]|[a-zA-Z][\w-]*)/gy;
  let tokens=[],i=0,line=1;
  while(i<text.length){tokenPattern.lastIndex=i;let m=tokenPattern.exec(text);
    if(!m)throw new Error('Line '+line+': unexpected token near '+JSON.stringify(text.slice(i,i+28))+'. Use the offline subset or a full Turtle parser.');
    let raw=m[0];if(!/^\s+$/.test(raw)&&!raw.startsWith('#'))tokens.push({v:raw,line});
    line+=(raw.match(/\n/g)||[]).length;i=tokenPattern.lastIndex;
  }
  let at=0;
  const peek=()=>tokens[at]?.v;
  const consume=()=>tokens[at++];
  function expand(t,ln){
    if(t==='a')return RDF_TYPE;
    if(/^[+-]?\d+$/.test(t))return '"'+t+'"^^<http://www.w3.org/2001/XMLSchema#integer>';
    if(/^[+-]?\d+\.\d+$/.test(t))return '"'+t+'"^^<http://www.w3.org/2001/XMLSchema#decimal>';
    if(t==='true'||t==='false')return '"'+t+'"^^<http://www.w3.org/2001/XMLSchema#boolean>';
    if(/^<[^<>\s]+>$/.test(t))return t.slice(1,-1);
    if(/^"(?:\\.|[^"\\])*"(?:@[a-zA-Z]+(?:-[a-zA-Z0-9]+)*|\^\^(?:<[^<>]+>|[\w-]*:[\w.-]+))?$/.test(t))return t;
    if(/^_:[A-Za-z][\w-]*$/.test(t))return t;
    let m=t.match(/^([\w-]*):([\w.-]+)$/);
    if(m){if(!(m[1] in prefix))throw new Error('Line '+ln+': unknown prefix '+m[1]+':');return prefix[m[1]]+m[2];}
    throw new Error('Line '+ln+': unexpected RDF term '+t+'.');
  }
  const term=()=>{let t=consume();if(!t)throw new Error('Incomplete statement: a subject, predicate or object is missing.');return expand(t.v,t.line);};
  while(at<tokens.length){
    let subject=term();if(subject.startsWith('"'))throw new Error('A literal cannot be the subject.');
    let finished=false;
    while(!finished){
      const predicate=term();if(predicate.startsWith('"'))throw new Error('A predicate must be an IRI.');
      let more=true;
      while(more){const object=term();quads.push({s:subject,p:predicate,o:object});
        if(peek()===','){consume();if(peek()==='.'||peek()===';'||peek()===undefined)throw new Error('Expected object after comma.');}else more=false;
      }
      if(peek()===';'){
        while(peek()===';')consume();
        if(peek()==='.') {consume();finished=true;}
        else if(peek()===undefined)throw new Error('Missing final period after last predicate.');
      }else if(peek()==='.') {consume();finished=true;}
      else throw new Error('Expected a period or semicolon after the statement near '+(peek()||'end of document')+'.');
    }
  }
  return {quads,prefix};
}
// Offline SPARQL subset. Full engine is provided in the downloadable Python labs.
function sparqlBasics(source,query){
  let prefixes={...BASE_PREFIXES};
  let q=query.replace(/^\s*PREFIX\s+([\w-]*):\s*<([^<>\s]+)>\s*$/gim,(_,key,url)=>{prefixes[key]=url;return '';}).trim();
  const match=q.match(/^SELECT\s+(DISTINCT\s+)?([?\w\s*]+?)\s+WHERE\s*\{([\s\S]*?)\}\s*(?:ORDER\s+BY\s+(?:(ASC|DESC)\s*\(\s*)?(\?[A-Za-z_]\w*)\s*\)?)?\s*(?:LIMIT\s+(\d+))?\s*(?:OFFSET\s+(\d+))?\s*$/i);
  if(!match)throw new Error('Offline query subset supports SELECT, DISTINCT, WHERE, joins, ORDER BY, LIMIT and OFFSET. For OPTIONAL, FILTER, GROUP BY and full SPARQL, run the Python enterprise lab.');
  const distinct=!!match[1],names=match[2].trim()==='*'?['*']:match[2].trim().split(/\s+/);
  if(!names.every(x=>x==='*'||/^\?[A-Za-z_][\w]*$/.test(x)))throw new Error('Use SELECT ?person ?course or SELECT *.');
  function expand(t){if(t[0]==='?')return t;if(t==='a')return RDF_TYPE;if(/^[+-]?\d+$/.test(t))return '"'+t+'"^^<http://www.w3.org/2001/XMLSchema#integer>';if(/^<[^<>\s]+>$/.test(t))return t.slice(1,-1);if(t.startsWith('"'))return t;let m=t.match(/^([\w-]*):([\w.-]+)$/);if(m){if(!(m[1] in prefixes))throw new Error('Unknown PREFIX '+m[1]+':');return prefixes[m[1]]+m[2];}throw new Error('Unsupported term '+t);}
  let where=match[3].trim();
  // A line-oriented subset: one triple pattern per line, terminated by a dot.
  const lines=where.split(/\n/).map(x=>x.trim()).filter(Boolean);
  if(!lines.length)throw new Error('Add at least one graph pattern.');
  const patterns=lines.map((line,idx)=>{if(!line.endsWith('.'))throw new Error('Pattern '+(idx+1)+' must end with a period.');let a=line.slice(0,-1).trim().match(/^(\S+)\s+(\S+)\s+(.+)$/);if(!a)throw new Error('Pattern '+(idx+1)+' needs subject predicate object.');return [expand(a[1]),expand(a[2]),expand(a[3])];});
  let rows=[{}];
  for(const [s,p,o] of patterns){let next=[];
    for(const prior of rows)for(const triple of source.quads){let possible={...prior},ok=true;
      for(const [pattern,value] of [[s,triple.s],[p,triple.p],[o,triple.o]]){
        if(pattern.startsWith('?')){let variable=pattern.slice(1);if(variable in possible&&possible[variable]!==value){ok=false;break;}possible[variable]=value;}
        else if(pattern!==value){ok=false;break;}
      }
      if(ok)next.push(possible);
    }
    rows=next;
  }
  let cols=names[0]==='*'?[...new Set(rows.flatMap(r=>Object.keys(r)))]:names.map(x=>x.slice(1));
  if(names[0]==='*'&&!cols.length)cols=[...new Set(patterns.flatMap(p=>p.filter(v=>v.startsWith('?')).map(v=>v.slice(1))))];
  let result=rows.map(r=>Object.fromEntries(cols.map(c=>[c,r[c]??''])));
  if(distinct){let seen=new Set();result=result.filter(r=>{let k=JSON.stringify(r);if(seen.has(k))return false;seen.add(k);return true;});}
  if(match[5]){let column=match[5].slice(1);const direction=match[4]?.toUpperCase()==='DESC'?-1:1;
    result.sort((a,b)=>direction*String(a[column]??'').localeCompare(String(b[column]??''),undefined,{numeric:true}));
  }
  if(match[7])result=result.slice(Number(match[7]));
  if(match[6])result=result.slice(0,Math.min(1000,Number(match[6])));
  return {rows:result,cols};
}
function fullTurtleValidator(){return new Promise((resolve,reject)=>{
  if(window.N3){resolve(window.N3);return;}
  let s=document.createElement('script');s.src='https://unpkg.com/n3/browser/n3.min.js';s.async=true;
  s.onload=()=>window.N3?resolve(window.N3):reject(new Error('N3.js did not load.'));
  s.onerror=()=>reject(new Error('Could not fetch N3.js. Check your internet connection or try again later.'));
  document.head.appendChild(s);
});}
async function checkTurtleFull(){turtleResult={pending:true,message:'Loading the full N3.js Turtle parser...'};render();
  try{let N3=await fullTurtleValidator();let quads=new N3.Parser({format:'text/turtle'}).parse(turtle);turtleResult={ok:true,message:'Valid Turtle according to N3.js: '+quads.length+' triples/quads parsed.',quads:quads.length,full:true};}
  catch(e){turtleResult={ok:false,message:e.message||String(e),full:true};}
  render();}
function checkTurtle(){try{parsedData=parseStarterTurtle(turtle);turtleResult={ok:true,message:'Starter syntax accepted: '+parsedData.quads.length+' triples found.',quads:parsedData.quads.length};}
  catch(e){turtleResult={ok:false,message:e.message};parsedData=null;}render();}
function runSparql(){try{let src=parseStarterTurtle(turtle);parsedData=src;queryResult={ok:true,...sparqlBasics(src,sparql)};}
  catch(e){queryResult={ok:false,error:e.message};}render();}
function resultRows(out){if(!out)return `<div class="empty-state">Run the code to see results. Choose a dataset above to start.</div>`;if(!out.ok)return `<div class="result-error">⚠ ${esc(out.error||out.message)}</div>`;
 return `<div class="row between" style="margin-bottom:14px"><span class="result-success">✓ Query completed</span><span class="tiny">${out.rows.length} result${out.rows.length===1?'':'s'}</span></div>${out.rows.length?`<table><thead><tr>${out.cols.map(c=>`<th>?${esc(c)}</th>`).join('')}</tr></thead><tbody>${out.rows.map(row=>`<tr>${out.cols.map(c=>`<td title="${esc(row[c])}">${esc(localTerm(row[c]))}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p>No matching rows. Check your graph patterns or try the sample query.</p>'}`;}
function turtleFeedback(){if(!turtleResult)return '<div class="empty-state">Check your code to see any syntax issues.</div>';return `<div class="${turtleResult.ok?'result-success':'result-error'}">${turtleResult.pending?'◷ ':turtleResult.ok?'✓ ':'⚠ '}${esc(turtleResult.message)}</div>${turtleResult.ok?`<p class="graph-note">${turtleResult.full?'Full syntax check by N3.js.':'For extended Turtle syntax, use the “Extended parser (online)” button.'}</p>`:''}`;}
